{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Server Room Incident",
          "intent": "Establish Artie's mundane life and the catalyst for his transition to Aethelgard.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Artie is electrocuted during a server-room surge and loses consciousness."
        },
        {
          "section_id": 2,
          "title": "The Glass Cannon Awakening",
          "intent": "Introduce the glitched status and the immediate danger of the 1 HP constraint.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie confirms his stats show 100% Critical Hit Chance and exactly 1/1 HP."
        },
        {
          "section_id": 3,
          "title": "The Tutorial Guardian",
          "intent": "Demonstrate the 'Hit & Run' combat style against the first major threat.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "The Tutorial Guardian is defeated without Artie taking a single point of damage."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "Mastering the Perfect Dodge",
          "intent": "Artie exploits the game's i-frame mechanics to survive low-level mob aggro.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "Artie successfully chains ten 'Perfect Dodges' in a single encounter."
        },
        {
          "section_id": 2,
          "title": "The Speedrunner's Shortcut",
          "intent": "Artie uses his knowledge of game geometry to bypass standard tutorial gates.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie reaches the hidden 'Developer's Backdoor' in the starter zone."
        },
        {
          "section_id": 3,
          "title": "The Hidden Achievement",
          "intent": "Secure the legendary-tier starter gear through a 'No-Hit' clear achievement.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The System grants the 'Untouchable Legend' title and the associated gear set."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "Into the Iron Peaks",
          "intent": "Transition from the safe tutorial zone to the high-stakes open world.",
          "section_role": "transition",
          "target_scene_count": 3,
          "end_condition": "Artie crosses the threshold into the Iron Peaks territory."
        },
        {
          "section_id": 2,
          "title": "Environmental Hazards",
          "intent": "Show that the environment is just as deadly as monsters for a 1 HP build.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "Artie survives a scripted rockslide using high-speed kiting."
        },
        {
          "section_id": 3,
          "title": "The Gates of Oakhaven",
          "intent": "Establish the next major obstacle: the social and guild-based gatekeeping.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie is refused entry to Oakhaven for lacking a guild voucher."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Spire Infiltration",
          "intent": "Artie sneaks into the solo-challenge dungeon to farm the necessary voucher.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie bypasses the external guards and enters the Infinite Spire instance."
        },
        {
          "section_id": 2,
          "title": "Climbing the Floors",
          "intent": "Demonstrate the scaling difficulty and Artie's reliance on one-shotting enemies.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie clears the tenth floor, triggering a system-wide difficulty spike."
        },
        {
          "section_id": 3,
          "title": "The Anti-Cheat Shadow",
          "intent": "Introduce the System's awareness of Artie's anomalous performance.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Artie receives a 'Suspicious Activity' notification from the System AI."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Disgraced Shield-Maiden",
          "intent": "Introduce Silna and establish her current low status in Oakhaven.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie locates Silna in a back-alley pit-fighting ring."
        },
        {
          "section_id": 2,
          "title": "The Tyrant's Heirloom",
          "intent": "Provide Silna with a motivation to join Artie's high-risk mission.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Silna agrees to the partnership in exchange for help reclaiming her family crest."
        },
        {
          "section_id": 3,
          "title": "The Unlikely Duo",
          "intent": "Establish the tactical synergy between a 1 HP crit-machine and a pure tank.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "Artie and Silna successfully complete a practice skirmish together."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Infiltrating the Red-Tier Keep",
          "intent": "The duo enters the highest-level zone in the region using stealth and speed.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Artie and Silna reach the inner sanctum of the Keep undetected."
        },
        {
          "section_id": 2,
          "title": "Setting up the Overflow",
          "intent": "Artie prepares the mechanical conditions for a massive damage exploit.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "All necessary debuffs are applied to the boss, and Artie's buffs are maxed."
        },
        {
          "section_id": 3,
          "title": "The One-Shot Kill",
          "intent": "The final execution of the exploit and the resulting world-state change.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Regional Boss is vaporized by a single hit, dropping the World Key."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Loot & The Chaos",
          "intent": "Artie and Silna secure the treasury rewards while the Keep collapses.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "The treasury is emptied and the World Key is secured in Artie's inventory."
        },
        {
          "section_id": 2,
          "title": "The Moderator Arrival",
          "intent": "Raise the stakes by introducing the physical manifestation of the Anti-Cheat AI.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "The System Moderators arrive at the Keep's ruins to investigate the glitch."
        },
        {
          "section_id": 3,
          "title": "The Great Escape",
          "intent": "Artie and Silna flee to the lawless zones to avoid deletion.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "Artie and Silna cross the border into the Grey Zones, vanishing from the System's primary radar."
        }
      ]
    }
  ]
}

